def __init__(self, buttons):
    super(ButtonGroup, self).__init__()
    self.get_style_context().add_class(Gtk.STYLE_CLASS_LINKED)
    for b in buttons:
        self.pack_start(b, False, False, 0)

def __init__(self, payment, bank_info, **kwargs):
    pdate = payment.due_date
    kwargs.update(
        penalty_date=pdate.strftime('%d%m%Y'),
    )
    super(ItauPenaltyDetail, self).__init__(**kwargs)

def __init__(self, filename, payments):
    self.booklets_data = list(self._get_booklets_data(payments))
    HTMLReport.__init__(self, filename)

def __init__(self, filename, client):
    self.client = client
    HTMLReport.__init__(self, filename)
